/// <summary>
/// Shipment and load creation for sales order
/// </summary>
class METOrderShipmentLoadCreation_SalesOrder extends METOrderShipmentLoadCreation
{
}

Method.Source:
/// <summary>
/// New method for the class
/// </summary>
public void new(SalesTable      _salesTable)
{
    salestable = _salesTable;
}

/// <summary>
/// Find or create new shipment
/// </summary>
/// <returns>METSalesOrderShipmentLoadHeader</returns>
public METSalesOrderShipmentLoadHeader findOrCreateOpenShipment(boolean _createIfNotFound = false)
{
    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;

    void findOpenShipment()
    {
        select firstonly metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.CustAccount == salesTable.CustAccount                 &&
                metSalesOrderShipmentLoadHeader.Route == salesTable.METRoute                            &&
                metSalesOrderShipmentLoadHeader.RouteStopNum == salesTable.METRouteStopNum              &&
                metSalesOrderShipmentLoadHeader.ConfirmedShipDate == salesTable.ShippingDateConfirmed   &&
                metSalesOrderShipmentLoadHeader.Warehouse == salesTable.InventLocationId                &&
                metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder  &&
                metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open;
    }

    findOpenShipment();

    if (metSalesOrderShipmentLoadHeader.RecId != 0 || _createIfNotFound == false)
    {
        return metSalesOrderShipmentLoadHeader;
    }

    metSalesOrderShipmentLoadHeader.clear();

    metSalesOrderShipmentLoadHeader.ShipmentId      = NumberSeq::newGetNum(InventParameters::numRefMetShippingID()).num();
    metSalesOrderShipmentLoadHeader.CustAccount     = salesTable.CustAccount;
    metSalesOrderShipmentLoadHeader.ConfirmedShipDate = salesTable.ShippingDateConfirmed;
    metSalesOrderShipmentLoadHeader.Route           = salesTable.METRoute;
    metSalesOrderShipmentLoadHeader.RouteStopNum    = salesTable.METRouteStopNum;
    metSalesOrderShipmentLoadHeader.Warehouse       = salesTable.InventLocationId;
    metSalesOrderShipmentLoadHeader.SiteId          = InventLocation::find(salesTable.InventLocationId).InventSiteId;
    metSalesOrderShipmentLoadHeader.TransactionType = METOrderTransactionType::SalesOrder;
    metSalesOrderShipmentLoadHeader.ShipmentStatus  = MetShipmentStatus::Open;

    if (metSalesOrderShipmentLoadHeader.validateWrite())
    {
        metSalesOrderShipmentLoadHeader.insert();
    }
    else //In case of validation fail, try again to search for open shipment. This may occur when multi thread is running and at same time two picking list executed and system tryed to insert shipment for same parameter.
    {
        findOpenShipment();

        return metSalesOrderShipmentLoadHeader;
    }

    return metSalesOrderShipmentLoadHeader;

}

/// <summary>
/// Create shipment lines
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">Table reference</param>
public void createShipmentLines(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
    boolean                             shipmentLineInserted;
    METPickingListSalesLine             metPickingListSalesLine;
    METSalesOrderShipmentLoadHeader     metShipmentHeader;
    RecordInsertList                    shipLinesRecordInsertList = new RecordInsertList(tableNum(METSalesOrderShipmentLoadLines), false, false, false, false, false);
    WMSOrderTrans                       wmsOrderTrans;        

    update_recordset metSalesOrderShipmentLoadLines
        setting ShipmentId = _metSalesOrderShipmentLoadHeader.ShipmentId
            where metSalesOrderShipmentLoadLines.OrderNum == salesTable.SalesId
        exists join metShipmentHeader
            where metShipmentHeader.ShipmentId != _metSalesOrderShipmentLoadHeader.ShipmentId      &&
                metshipmentheader.ShipmentStatus == METShipmentStatus::Open;

    while select metPickingListSalesLine
        where metPickingListSalesLine.CustAccount == _metSalesOrderShipmentLoadHeader.CustAccount    &&
            metPickingListSalesLine.METRoute    == _metSalesOrderShipmentLoadHeader.Route            &&
            metPickingListSalesLine.METRouteStopNum == _metSalesOrderShipmentLoadHeader.RouteStopNum &&
            metPickingListSalesLine.ShippingDateConfirmed == _metSalesOrderShipmentLoadHeader.ConfirmedShipDate &&
            metPickingListSalesLine.InventLocationId == _metSalesOrderShipmentLoadHeader.Warehouse   &&
            metPickingListSalesLine.SalesId == salesTable.SalesId
    {
        // To fetch the pictlist cw qty value
        select firstonly PdsCWQty from wmsOrderTrans
                    where wmsOrderTrans.inventTransId == metPickingListSalesLine.InventTransId;

        metSalesOrderShipmentLoadLines.clear();

        metSalesOrderShipmentLoadLines.ShipmentId       = _metSalesOrderShipmentLoadHeader.ShipmentId;
        metSalesOrderShipmentLoadLines.OrderNum         = metPickingListSalesLine.SalesId;
        metSalesOrderShipmentLoadLines.LineNum          = metPickingListSalesLine.LineNum;
        metSalesOrderShipmentLoadLines.ItemId           = metPickingListSalesLine.ItemId;
        metSalesOrderShipmentLoadLines.Quantity         = metPickingListSalesLine.SalesQty;
        metSalesOrderShipmentLoadLines.BackOrder        = metPickingListSalesLine.METAllowBackOrders;
        metSalesOrderShipmentLoadLines.OrderSplitGroup  = METSalesTable::findByRefRecId(SalesTable::find(metPickingListSalesLine.SalesId).RecId).OrderSplitGroup;
        metSalesOrderShipmentLoadLines.InventTransId    = metPickingListSalesLine.InventTransId;
        metSalesOrderShipmentLoadLines.PickedQty        = metPickingListSalesLine.PickedQty;
        metSalesOrderShipmentLoadLines.PickingListNum   = metPickingListSalesLine.PickListNum;
        metSalesOrderShipmentLoadLines.PickListPostedBy = metPickingListSalesLine.PickListPostedBy;
        metSalesOrderShipmentLoadLines.WMSOrderTransRecId = metPickingListSalesLine.WMSOrderTransRecId;
        metSalesOrderShipmentLoadLines.PickListPostedDateTime = metPickingListSalesLine.PickListPostedDateTime;
        metSalesOrderShipmentLoadLines.CWOrderQuantity  = SalesLine::findInventTransId(metPickingListSalesLine.InventTransId).PdsCWExpectedRetQty;
        metSalesOrderShipmentLoadLines.CWQuantity = wmsOrderTrans.PdsCWQty;
        metSalesOrderShipmentLoadLines.DeliveryInstructions = METSalesTable::findByRefRecId(SalesTable::find(metPickingListSalesLine.SalesId).RecId).DeliveryInstructions;

        shipLinesRecordInsertList.add(metSalesOrderShipmentLoadLines);

        shipmentLineInserted = true;
    }

    if (shipmentLineInserted)
    {
        shipLinesRecordInsertList.insertDatabase();
    }
}

/// <summary>
/// Init load query 
/// </summary>
/// <param name = "_metRoute">Route reference</param>
/// <param name = "_confirmedDate">Confirmed date</param>
/// <param name = "_warehouse">Warehouse</param>
/// <returns>Query</returns>
public Query initFindLoadQuery(METRoute _metRoute, SalesShippingDateConfirmed _confirmedDate, InventLocationId _warehouse)
{
    Query salesLoadQuery;

    salesLoadQuery = super(_metRoute, _confirmedDate, _warehouse);

    salesLoadQuery.dataSourceTable(tableNum(METSalesOrderShipmentLoadHeader)).addRange(fieldNum(METSalesOrderShipmentLoadHeader, Warehouse)).value(queryValue(_warehouse));
    salesLoadQuery.dataSourceTable(tableNum(METSalesOrderShipmentLoadHeader)).addRange(fieldNum(METSalesOrderShipmentLoadHeader, TransactionType)).value(queryValue(METOrderTransactionType::SalesOrder));


    return salesLoadQuery;
}
